}
const nose=new THREE.Mesh(eyeGeo,pinkM);nose.scale.set(.022,.018,.012);nose.position.set(0,-.035,.215);head.add(nose);
for(const side of [-1,1]){box(head,side*.15,-.04,.16,.2,.006,.006,whiteM,false)}
const legs=[];
for(const lx of [-.14,.14])for(const lz of [-.18,.2]){
  const hip=new THREE.Group();hip.position.set(lx,.3,lz);g.add(hip);
  const leg=new THREE.Mesh(capsuleGeoMake(.038,.15),bodyM);leg.position.y=-.12;hip.add(leg);
  sphere(hip,0,-.23,.02,.045,whiteM);legs.push(hip);
}
const tail=new THREE.Group();tail.position.set(0,.42,-.37);g.add(tail);
const t1=new THREE.Mesh(capsuleGeoMake(.04,.18),bodyM);t1.position.set(0,.08,-.08);t1.rotation.x=-.7;tail.add(t1);
const t2=new THREE.Mesh(capsuleGeoMake(.033,.14),bodyM);t2.position.set(0,.19,-.22);t2.rotation.x=-.3;tail.add(t2);
