import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002/?v=' + Date.now(), { waitUntil: 'load' });
await page.waitForTimeout(1600);
await page.locator('#start-button').click();
await page.waitForTimeout(5000);
async function tp(x, z) { await page.evaluate(([x, z]) => window.__dbg.teleport(x, z), [x, z]); await page.waitForTimeout(700); }
async function cam(px, py, pz, tx, ty, tz, name) {
  await page.evaluate(([px, py, pz, tx, ty, tz]) => {
    window.__freezeCamera = true;
    window.__dbg.camera.position.set(px, py, pz);
    window.__dbg.camera.lookAt(tx, ty, tz);
  }, [px, py, pz, tx, ty, tz]);
  await page.waitForTimeout(500);
  await page.screenshot({ path: `/tmp/opencode/v7-${name}.png` });
  await page.evaluate(() => { window.__freezeCamera = false; });
}
// Archive interior from inside the door, eye-level.
await tp(-24, 14);
await cam(-17.8, 3.05, 14, -27, 1.6, 12.5, 'archive-in');
// Wide archive overview.
await cam(-17.6, 5.2, 20.8, -31, 1.2, 12.4, 'archive-wide');
// Bird front and side, low and close.
await tp(40, 40);
const bird = [-2, 44];
await page.evaluate(([x, z]) => { const b = window.__dbg.birds[0]; b.state = 'ground'; b.group.position.set(x, 0, z); b.group.rotation.set(0, 0, 0); b.home = { x, z }; }, bird);
await cam(bird[0], 0.62, bird[1] + 1.55, bird[0], 0.42, bird[1], 'bird-front');
await cam(bird[0] + 1.45, 0.68, bird[1] + 0.7, bird[0], 0.42, bird[1], 'bird-side');
// Cat side.
const cat = [-18, 12];
await page.evaluate(([x, z]) => { const c = window.__dbg.cats[0]; c.group.position.set(x, 0, z); c.group.rotation.y = 0; }, cat);
await tp(40, 40);
await cam(cat[0] + 1.9, 0.72, cat[1] + 0.65, cat[0], 0.4, cat[1], 'cat-side');
// Market and Spire density.
await tp(-51, 30);
await cam(-51, 3.2, 21, -51, 1.2, 30, 'market-in');
await tp(28, -50);
await cam(28, 3.05, -44.3, 28, 1.4, -54, 'spire-in');
console.log('errors', errors);
await browser.close();

