function collidesAt(x,z,r=PLAYER_RADIUS,kind=null){
  for(const c of colliders){
    if(c.open)continue;
    if(kind&&c.kind!==kind)continue;
    if(x+r>c.x1&&x-r<c.x2&&z+r>c.z1&&z-r<c.z2)return true;
  }
  return false;
}

