let activeRoom=null;
function updateCamera(dt){
  const room=interiorAt(player.position.x,player.position.z,0);
  activeRoom=room;
  if(window.__freezeCamera)return;
  const target=new THREE.Vector3(player.position.x,player.position.y+1.45,player.position.z);
  if(room){
    // Keep the camera inside the room and in front of the wall so interiors are never
    // transparent to the street. Walls stay solid; the camera slides along them instead.
    const distance=3.9,horizontal=distance*Math.cos(pitch);
    const desired=new THREE.Vector3(target.x+Math.sin(yaw)*horizontal,target.y+.95+Math.sin(pitch)*distance,target.z+Math.cos(yaw)*horizontal);
    desired.x=THREE.MathUtils.clamp(desired.x,room.x-room.w/2+1.0,room.x+room.w/2-1.0);
    desired.z=THREE.MathUtils.clamp(desired.z,room.z-room.d/2+1.0,room.z+room.d/2-1.0);
    desired.y=THREE.MathUtils.clamp(desired.y,1.35,room.h-.65);
    let safe=1;
    for(let i=1;i<=16;i++){const f=i/16,cx=target.x+(desired.x-target.x)*f,cz=target.z+(desired.z-target.z)*f;if(collidesAt(cx,cz,.16,'wall')){safe=Math.max(.2,(i-1)/16);break}}
    const clipped=target.clone().lerp(desired,safe);
    clipped.y=Math.max(clipped.y,1.25);
    camera.position.lerp(clipped,1-Math.exp(-dt*6));
    camera.lookAt(target.x,target.y+.35,target.z);
    return;
  }
  const distance=7.8;
  const horizontal=distance*Math.cos(pitch);
  const desired=new THREE.Vector3(target.x+Math.sin(yaw)*horizontal,target.y+2.2+Math.sin(pitch)*distance,target.z+Math.cos(yaw)*horizontal);
  let safe=1;
  for(let i=1;i<=18;i++){const f=i/18,cx=target.x+(desired.x-target.x)*f,cz=target.z+(desired.z-target.z)*f;if(collidesAt(cx,cz,.24)){safe=Math.max(.14,(i-1)/18);break}}
  const clipped=target.clone().lerp(desired,safe);
