const port=process.env.PORT||9225;
const url=process.env.URL||'http://127.0.0.1:8123/index.html';
const t=await (await fetch(`http://127.0.0.1:${port}/json/new?${encodeURIComponent(url)}`,{method:'PUT'})).json();
const ws=new WebSocket(t.webSocketDebuggerUrl);
let id=0;const pending=new Map();const logs=[];
const send=(method,params={})=>new Promise((res,rej)=>{const i=++id;pending.set(i,{res,rej});ws.send(JSON.stringify({id:i,method,params}))});
ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.rej(new Error(JSON.stringify(m.error))):p.res(m.result)}else if(['Runtime.exceptionThrown','Log.entryAdded','Runtime.consoleAPICalled'].includes(m.method)){logs.push(m)}};
await new Promise(r=>ws.onopen=r);
await send('Runtime.enable');await send('Log.enable');await send('Page.enable');
await new Promise(r=>setTimeout(r,9000));
async function ev(expr){const r=await send('Runtime.evaluate',{expression:expr,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)return {error:r.exceptionDetails.text,detail:r.exceptionDetails.exception?.description};return r.result.value}
const state=await ev(`(()=>{const d=window.__dbg;return {dbg:!!d, started:!!document.querySelector('#start-button')?.closest('.hidden'), interiors:d?.interiors?.length, entities:d?.entities?.length, birds:d?.birds?.length, cats:d?.cats?.length, colliders:d?.colliders?.length, audio:!!document.querySelector('#audio-toggle'), map:document.querySelector('#minimap')?.width, webgl:!!document.querySelector('#game')?.getContext('webgl2')}})()`);
console.log('STATE',JSON.stringify(state,null,2));
console.log('LOGS',logs.map(l=>l.method+': '+JSON.stringify(l.params).slice(0,800)).join('\n'));
const shot=await send('Page.captureScreenshot',{format:'png'}).catch(e=>({error:e.message}));
if(shot.data){const fs=await import('node:fs');fs.writeFileSync('/tmp/opencode/shot1.png',Buffer.from(shot.data,'base64'));console.log('shot saved')}
ws.close();

