  if(Math.abs(x+51)<10&&Math.abs(z-27)<9)return 'MARKET 09';
  if(Math.abs(x+51)<9.5&&Math.abs(z-52)<8.5)return 'CIVIC POLICE';
  if(Math.abs(x-51)<10&&Math.abs(z-27)<9)return 'POST OFFICE';
