function openPuzzle(ent){
  puzzleEntity=ent;document.exitPointerLock?.();tones=[-1,-1,-1];dials=[1,1,1];circuits=[0,0,0,0];
  const body=$('#tone-row');body.innerHTML='';body.className='tone-row';
