```js
function batchPart(root){
  const buckets=new Map();
  for(const child of root.children){
    if(!child.isMesh||child.isInstancedMesh)continue;
    if(child.userData.dynamic)continue;
    const mat=child.material;
    if(!mat||Array.isArray(mat)||mat.transparent)continue;
    const g=child.geometry;
    if(!g||!g.attributes.position)continue;
    const attrs=Object.keys(g.attributes).sort().join(',');
    const key=mat.uuid+'|'+(child.castShadow?1:0)+'|'+(g.index?1:0)+'|'+attrs;
    let b=buckets.get(key);if(!b){b={mat,cast:child.castShadow,receive:child.receiveShadow,geos:[]};buckets.set(key,b)}
    child.updateMatrix();
    b.geos.push(child);
  }
  for(const b of buckets.values()){
    if(b.geos.length<2)continue;
    const geos=b.geos.map(m=>{const g=m.geometry.clone();g.applyMatrix4(m.matrix);return g});
    const merged=mergeGeometries(geos,false);
    geos.forEach(g=>g.dispose());
    if(!merged)continue;
    const mesh=new THREE.Mesh(merged,b.mat);
    mesh.castShadow=b.cast;mesh.receiveShadow=b.receive;
    root.add(mesh);
    for(const m of b.geos)root.remove(m);
  }
}
```
