    camDesired.z=THREE.MathUtils.clamp(camDesired.z,room.z-room.d/2+.72,room.z+room.d/2-.72);
    camDesired.y=THREE.MathUtils.clamp(camDesired.y,1.30,room.h-.50);
    let cx=camTarget.x,cz=camTarget.z;
    let safe=1;
    for(let i=1;i<=24;i++){
